 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find each solid 2x2 block of color 2 and its four diagonal neighbors.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))

    for r, c in blocks:
        coords = [(r - 1, c - 1), (r - 1, c + 2),
                  (r + 2, c - 1), (r + 2, c + 2)]  # NW, NE, SW, SE
        if not all(0 <= rr < h and 0 <= cc < w for rr, cc in coords):
            continue
        nw, ne, sw, se = [grid[rr][cc] for rr, cc in coords]
        colors = [sw, nw, se, ne]  # clockwise rotation of the four colors
        dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for (rr, cc), color, (dr, dc) in zip(coords, colors, dirs):
            out[rr][cc] = color
            y, x = rr + dr, cc + dc
            while 0 <= y < h and 0 <= x < w:
                out[y][x] = color
                y += dr
                x += dc
    return out
